const isBad=r=>r.http>=400||['failed','incomplete'].includes(r.semantic)||['failed','interrupted'].includes(r.transport)||(r.transport==='cancelled'&&r.semantic!=='completed');
const percentile=vals=>{vals=vals.filter(v=>v!==null&&Number.isFinite(v)).sort((a,b)=>a-b);return vals.length?Math.round(vals[Math.ceil(vals.length*.95)-1]):null;};
